CREATE TABLE IF NOT EXISTS node_comment_read (user_id BIGINT NOT NULL, mind_map_id BIGINT NOT NULL, node_id VARCHAR(64) NOT NULL, last_read_id BIGINT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (user_id, mind_map_id, node_id), KEY idx_mindmap (mind_map_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; SHOW TABLES LIKE 'node_comment_read';
